// Complex Nested Generics
// =========================================================================

final class TokenRegistry[T] {
  private val registry = mutable.Map.empty[String, TokenContainer[T]]
  private val handlers = mutable.ListBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry.update(key, container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.toList.map { item =>
          handlers.iterator.map(_(item)).find(_.isDefined).getOrElse(None)
        }
    }
  }
}

// =========================================================================
// Higher-Kinded Type Simulation
// =========================================================================

class TokenFunctor[T](private var value: T) {
  def map[U](func: T => U): TokenFunctor[U] = new TokenFunctor(func(value))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = func(value)

  def getOrElse(default: T): T = if (value == null) default else value

  def get: T = value
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = TokenMonad(funcWrapped.get.apply(get))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)

  def apply[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// =========================================================================
// JSON Structure Tokenization
// =========================================================================

final class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def step(current: Json, remaining: List[String]): Option[Json] = remaining match {
      case Nil => Some(current)
      case head :: tail =>
        current.asObject.flatMap(_.apply(head)) match {
          case Some(next) => step(next, tail)
          case None =>
            current.asArray.flatMap { arr =>
              if (head.forall(_.isDigit)) {
                val idx = head.toInt
                if (idx >= 0 && idx < arr.size) Some(arr(idx)) else None
              } else None
            } match {
              case Some(next) => step(next, tail)
              case None => None
            }
        }
    }

    step(value, parts).map(tokenize)
  }
}

// =========================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// =========================================================================

final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def stripWord(word: String): String = {
    var start = 0
    var end = word.length
    while (start < end && punctuation.contains(word.charAt(start))) start += 1
    while (end > start && punctuation.contains(word.charAt(end - 1))) end -= 1
    word.substring(start, end)
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripWord(word) else word
    val normalized = if (lowercase) stripped.toLowerCase else stripped

    if (normalized.length < minLength) return None

    val truncated = maxLength match {
      case Some(max) if normalized.length > max => normalized.substring(0, max)
      case _ => normalized
    }

    if (truncated.isEmpty) None else Some(truncated)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val tokens = mutable.ListBuffer.empty[Token]

    for ((word, index) <- words.zipWithIndex) {
      processToken(word).foreach { processed =>
        tokens += Token(processed, TokenType.STRING, Map("position" -> index, "original" -> word))
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// =========================================================================
// Builder Pattern with Fluent Interface
// =========================================================================

final class TokenizerBuilder[T] private () {
  private var normalizers = Vector.empty[String => String]
  private var validators = Vector.empty[T => Boolean]
  private var metadata = Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(kv: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ kv.toMap
    this
  }

  def build(): T => Token = {
    val normalizersSnapshot = normalizers
    val validatorsSnapshot = validators
    val metadataSnapshot = metadata

    (value: T) => {
      validatorsSnapshot.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString
      normalizersSnapshot.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadataSnapshot)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
